import{_ as s,o as a,c as i,a3 as t}from"./chunks/framework.WFmvnizL.js";const k=JSON.parse('{"title":"Testing, contributions, and release checks","description":"Test and contribute to Nezha Monitoring with Go tests, race and vet, frontend checks, documentation builds, pinned cross-repository integration, browser validation, and review evidence.","frontmatter":{"description":"Test and contribute to Nezha Monitoring with Go tests, race and vet, frontend checks, documentation builds, pinned cross-repository integration, browser validation, and review evidence.","outline":"deep"},"headers":[],"relativePath":"en_US/developer/testing.md","filePath":"en_US/developer/testing.md","lastUpdated":1792850916000}'),n={name:"en_US/developer/testing.md"};function r(o,e,l,d,h,p){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="testing-contributions-and-release-checks" tabindex="-1">Testing, contributions, and release checks <a class="header-anchor" href="#testing-contributions-and-release-checks" aria-label="Permalink to &quot;Testing, contributions, and release checks&quot;">​</a></h1><p>Match verification to the layer changed. Documentation-only work need not rebuild Agent; protocol/lifecycle work needs more than a working homepage. These are checks developers can run, not a claim that every project suite has already been executed for each change.</p><h2 id="go-backend-and-agent" tabindex="-1">Go backend and Agent <a class="header-anchor" href="#go-backend-and-agent" aria-label="Permalink to &quot;Go backend and Agent&quot;">​</a></h2><p>Prepare Dashboard Swagger and nonempty frontend assets using the <a href="/en_US/developer/getting-started.html">quick start</a>, then run from each repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -mod=readonly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -count=1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -mod=readonly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -race</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -shuffle=on</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -count=1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span></code></pre></div><p><code>-race</code> requires a supported platform and C compiler. Functional and race checks are complementary. Regression tests should reproduce the bug, not merely mirror implementation.</p><p>Both repositories&#39; <code>.github/workflows/test.yml</code> include ordinary, race/quality, and cross-repository stress verification. <code>agentcompat</code> uses pinned source combinations and dedicated build tags. For reporting, reconnection, exactly-once task execution, or shutdown changes, reuse those pinned scenarios rather than dropping steps or replacing revisions with arbitrary latest versions.</p><h2 id="user-theme" tabindex="-1">User theme <a class="header-anchor" href="#user-theme" aria-label="Permalink to &quot;User theme&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div><p>The current script combines code checks, coverage, type checking, and production build. Coverage does not prove chart appearance; mocks/doubles do not prove real authorization, recovery, or asset publication. Check frontend main and the Dashboard manifest&#39;s bundled version separately.</p><h2 id="admin-frontend" tabindex="-1">Admin frontend <a class="header-anchor" href="#admin-frontend" aria-label="Permalink to &quot;Admin frontend&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>For real login/form/routing integration, start an isolated backend following the repository README, then prepare browsers and run Playwright:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e:install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e</span></span></code></pre></div><p>E2E changes admin state: never point it at production. Preserve reports, backend logs, and failing URLs while removing credentials.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>Run from the documentation repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p><code>npm test</code> includes VitePress build, SEO/bilingual-page/internal-link auditing, and MCP component tests. New pages need synchronized Chinese/English navigation, related links, and appropriate <code>llms.txt</code> entries. Descriptions should accurately state the problem a page solves.</p><h2 id="browser-verification-matrix" tabindex="-1">Browser verification matrix <a class="header-anchor" href="#browser-verification-matrix" aria-label="Permalink to &quot;Browser verification matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Minimum coverage</th></tr></thead><tbody><tr><td>Identity</td><td>Guest, member, admin, expired session, mandatory login</td></tr><tr><td>Routing</td><td>Direct open/refresh, client navigation, HTTP status, asset base</td></tr><tr><td>Data</td><td>Empty fleet, offline, missing fields, TSDB on/off, empty history</td></tr><tr><td>Failure</td><td>Network loss/recovery, timeouts, out-of-order requests, retryable failures</td></tr><tr><td>Layout</td><td>Desktop, narrow screens, long text, light/dark, keyboard focus</td></tr></tbody></table><p>Record browser and viewport. Simulated narrow screens are not physical-phone tests. Mark unrun checks as unverified instead of substituting unit results for visual findings.</p><h2 id="submission-and-rollback" tabindex="-1">Submission and rollback <a class="header-anchor" href="#submission-and-rollback" aria-label="Permalink to &quot;Submission and rollback&quot;">​</a></h2><p>Use an isolated branch. Describe the issue, change, compatibility, and checks actually run. Follow repository lockfile/generated-output rules. Never submit development databases, logged tokens, or test-user credentials.</p><p>Retain prior theme artifacts; provide <a href="/en_US/guide/q5.html">backup/recovery</a> for storage/configuration changes; record paired Dashboard/Agent commits for protocol work. Publishing, merging, and deploying are distinct from local verification: a successful build does not mean a change is live.</p>`,25)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
